// LinkedIn — Find the Celebrity (LeetCode 277). Everyone knows the celebrity; the celebrity knows no one.
// `knows(a, b)` is an expensive API: at most 3(n-1) calls.
public static class Celebrity {
    public static int Find(int n, Func<int, int, bool> knows) {
        if (n <= 0) return -1;
        int c = 0;
        for (int i = 1; i < n; i++) if (knows(c, i)) c = i;      // if c knows i, c is not the celebrity; i might be
        for (int i = 0; i < n; i++) {
            if (i == c) continue;
            if (knows(c, i) || !knows(i, c)) return -1;           // verify: the candidate may still fail
        }
        return c;
    }
}
