public static class Playground {
    public static void Main() {
        try {
            var k = Party(6, 3, out var calls);
            Expect.Do("celebrity 3 of 6", () => { Expect.Eq("celebrity 3 of 6", Celebrity.Find(6, k), 3); });
            Expect.Do("no celebrity", () => { Expect.Eq("no celebrity", Celebrity.Find(6, Party(6, -1, out _, 4)), -1); });
            bool[,] m = { { false, true }, { true, false } };
            Expect.Do("two people who know each other", () => { Expect.Eq("two people who know each other", Celebrity.Find(2, (a, b) => m[a, b]), -1); });
        } catch (Exception e) { Expect.Setup(e); }
        Expect.Summary(6);
    }

    // helpers used by the examples
    static Func<int, int, bool> Party(int n, int celeb, out Func<int> calls, int noise = 1) {
        int c = 0; var rnd = new Random(noise);
        var m = new bool[n, n];
        for (int a = 0; a < n; a++) for (int b = 0; b < n; b++) if (a != b) m[a, b] = rnd.Next(3) == 0;
        if (celeb >= 0) for (int a = 0; a < n; a++) { if (a != celeb) { m[a, celeb] = true; m[celeb, a] = false; } }
        calls = () => c;
        return (a, b) => { if (a == b) throw new InvalidOperationException("knows(i, i) called"); c++; return m[a, b]; };
    }
}

